/**
 * The Fleece
 * ----------
 * Gideon lays a wool fleece on the threshing floor: dew on the fleece alone, then dry fleece on wet ground. Stage: a threshing floor at dawn, a single fleece glistening with dew, the ground around it parched; silence, patience, and a second night reversed.
 *
 * Palette 0x1a1420 → 0x0a0502 · light: dew · hero: pillar
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./gideon-kit.js.
 */

import { THREE, createScene, house, pillar, person } from './gideon-kit.js';

const BG = 0x1a1420;
const GROUND = 0x0a0502;

export function build(group) {
    const W = createScene(group, { seed: 1128342543, bg: BG, fogNear: 55, fogFar: 220 });

    /* light — dew */
    W.lights({ sky: 0x9ab4d0, gnd: 0x5a5a52, hemi: 0.75, sun: 0xffd9a0, sunI: 0.95, sunPos: [-45, 16, 26] });

    W.disc([-30, 70, -150], 10, 0xfff8e8);
    const clouds = W.grp(group, [0, 0, 0], { name: 'cloud_bank' });
    [[-40, 44, -125, 26], [30, 50, -135, 32], [85, 42, -120, 22]].forEach(([x, y, z, s]) => {
        W.add(clouds, W.G('ico', 1, 1), W.mat(0xf0f4f8, { opacity: 0.75 }), [x, y, z], { s: [s, s * 0.22, s * 0.5] });
    });
    W.backdrop(clouds);

    /* ground */
    W.ground(260, 260, 0, 0, 0x0a0502, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* house: mud-brick walls, flat roof, door */
    house(W, group, -13, 0, -18, 1.0 + W.r() * 0.3, { mud: 0x0a0502 });
    house(W, group, -29, 0, -9, 0.8 + W.r() * 0.3, { mud: 0x0a0502 });

    /* hero: the standing stone */
    pillar(W, group, 0, 0, 0, 1.15, { stone: 0x0a0502 });
    W.disc([0, 6, -12], 5, 0x221a2a, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x1a1420, ry: 0.12, s: 1.02 });

    return W.finish();
}

export default { build };
